func:
// ENTRADA: msg.payload = los 16 input registers (enteros de 0 a 65535)
// SALIDA:  msg.payload = los datos en unidades reales, agrupados por bloque

const r = msg.payload;
if (!Array.isArray(r) || r.length < 16) {
    return null;                      // respuesta incompleta: no seguimos
}

const int16  = (v) => v >= 32768 ? v - 65536 : v;  // registros con signo
const uint32 = (alta, baja) => alta * 65536 + baja; // datos que ocupan 2 registros

const ESTADOS = ["PARADO", "ARRANCANDO", "EN MARCHA", "FRENANDO", "AVERÍA"];
const AVERIAS = ["Sin avería", "Sobretemperatura de rodamiento",
                 "Vibración elevada", "Pérdida de red", "Sobrevelocidad"];

msg.payload = {
    viento: {
        velocidad_mps: r[0] / 10,
        direccion_deg: r[5] / 10
    },
    rotor: {
        rpm:           r[1] / 100,
        pitch_deg:     r[2] / 100,
        yaw_deg:       r[6] / 10,
        generador_rpm: r[10]
    },
    produccion: {
        potencia_kw:   uint32(r[3], r[4]),
        par_nm:        r[11] * 10,
        energia_kwh:   uint32(r[12], r[13]) / 10
    },
    condicion: {
        vibracion_mms:        r[7] / 100,
        temp_rodamiento_c:    int16(r[8]) / 10,
        temp_multiplicador_c: int16(r[9]) / 10
    },
    estado: {
        codigo:        r[14],
        nombre:        ESTADOS[r[14]] ?? "DESCONOCIDO",
        averia_codigo: r[15],
        averia:        AVERIAS[r[15]] ?? "Desconocida"
    }
};
return msg;

// ENTRADA: el mensaje decodificado (bloques viento, rotor, produccion...)
// SALIDA:  msg.payload = una fila plana: una columna por medida + la etiqueta

const p = msg.payload;
msg.payload = {
    viento:             p.viento.velocidad_mps,
    potencia:           p.produccion.potencia_kw,
    rotor_rpm:          p.rotor.rpm,
    pitch:              p.rotor.pitch_deg,
    vibracion:          p.condicion.vibracion_mms,
    temp_rodamiento:    p.condicion.temp_rodamiento_c,
    temp_multiplicador: p.condicion.temp_multiplicador_c,
    estado:             p.estado.codigo,
    averia:             p.estado.averia_codigo,
    // etiqueta: lo que está pasando DE VERDAD (lo fija el botón de escenario)
    escenario:          flow.get("escenario") || "normal"
};
return msg;

// ENTRADA: un pulso cada 45 s
// SALIDA:  viento y turbulencia nuevos (HR1 en 0,1 m/s · HR6 en 0,1 %)
// Así la recogida recorre toda la curva de potencia y no solo el viento de hoy.

const viento      = 3 + Math.random() * 15;        // 3-18 m/s
const turbulencia = 2 + Math.random() * 10;        // 2-12 %
node.status({ text: `viento ${viento.toFixed(1)} m/s · turbulencia ${turbulencia.toFixed(0)} %` });
return [[
    { payload: { value: Math.round(viento * 10),      fc: 6, unitid: 1, address: 1, quantity: 1 } },
    { payload: { value: Math.round(turbulencia * 10), fc: 6, unitid: 1, address: 6, quantity: 1 } }
]];

// ENTRADA: msg.payload = nombre del escenario (botones de la izquierda)
// SALIDA:  escrituras Modbus (holding registers) para provocarlo
//   HR0 modo (0 auto, 1 manual) · HR3 consigna de yaw (0,1°) · HR4 límite (kW) · HR5 avería

const escenario = msg.payload;
const PLANES = {
    "normal":       { 0: 0, 4: 5000, 5: 0 },
    // modo manual con la góndola fija 35° fuera del viento (235°): produce menos, sin alarma
    "desalineada":  { 0: 1, 2: 200, 3: 2000, 4: 5000, 5: 0 },
    // un operador de red limita la potencia (curtailment): cambio de régimen legítimo
    "limitada":     { 0: 0, 4: 3000, 5: 0 },
    "averia-vibracion":  { 0: 0, 4: 5000, 5: 2 },
    "averia-rodamiento": { 0: 0, 4: 5000, 5: 1 }
};
const plan = PLANES[escenario];
if (!plan) {
    node.warn("Escenario desconocido: " + escenario);
    return null;
}
flow.set("escenario", escenario);
node.status({ fill: escenario === "normal" ? "green" : "orange", shape: "dot", text: escenario });

return [Object.entries(plan).map(([adr, valor]) => ({
    payload: { value: valor, fc: 6, unitid: 1, address: Number(adr), quantity: 1 }
}))];
